.ui-render {
  @apply flex flex-col justify-center items-center h-screen w-screen;
}

.ui-render > div {
  @apply bg-blue-500 h-full w-full flex justify-center items-center;
}

.ui-render > div > h1 {
  @apply text-5xl text-white;
}
